import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { PNG } from 'pngjs';
const root=path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/,'$1'));
const out=path.join(root,'EXPECTED');fs.mkdirSync(out,{recursive:true});
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const load=n=>PNG.sync.read(fs.readFileSync(path.join(root,'ORIGINALS/resource_pack/textures/ui',n+'.png')));
const W=500,H=301,BG=[32,48,64,255];
const plane=()=>{const p=new PNG({width:W,height:H});for(let i=0;i<p.data.length;i+=4)p.data.set(BG,i);return p};
// Independent piecewise point pull, including source/output cuts; no product imports.
function axis(i,D,S,a,b){if(i<a)return i;if(i>=D-b)return S-(D-i);const ds=D-a-b,ss=S-a-b;if(ds<=0||ss<=0)throw Error('degenerate slice not licensed by this protocol');return a+Math.floor((i-a+0.5)*ss/ds)}
function over(p,x,y,c,alpha=1){const i=4*(y*W+x),a=c[3]/255*alpha;if(a===0)return;for(let k=0;k<3;k++)p.data[i+k]=Math.round(c[k]*a+p.data[i+k]*(1-a));p.data[i+3]=255}
function slice(p,img,box,cuts,visibleWidth=box[2]){const[x,y,w,h]=box,[l,t,r,b]=cuts;for(let j=0;j<h;j++)for(let i=0;i<Math.min(w,visibleWidth);i++){const sx=axis(i,w,img.width,l,r),sy=axis(j,h,img.height,t,b),k=4*(sy*img.width+sx);over(p,x+i,y+j,img.data.subarray(k,k+4))}}
const cases=[];
function save(id,p,details){const png=PNG.sync.write(p),raw=Buffer.from(p.data);fs.writeFileSync(path.join(out,id+'.png'),png);fs.writeFileSync(path.join(out,id+'.rgba'),raw);cases.push({id,targetSelector:'[data-file-transmission-material-plane="'+id+'"]',wholePlane:[0,0,W,H],png:'EXPECTED/'+id+'.png',rgba:'EXPECTED/'+id+'.rgba',pngSha256:hash(png),rgbaSha256:hash(raw),...details})}
const frame=plane();for(let y=107;y<194;y++)for(let x=120;x<380;x++)over(frame,x,y,[9,9,9,255],.8);slice(frame,load('dialog_background_hollow_2'),[116,103,268,95],[8,23,8,42]);
save('frame-fill',frame,{frameBox:[116,103,268,95],fillBox:[120,107,260,87],fillAlpha:.8,paintIsolation:'All title/description/warning glyph paint, all buttons, both progress image paint and nub paint, platform logo paint visibility:hidden; preserve boxes/geometry. Source common_panel close remains ignored defaultfalse.'});
for(const fraction of [0,.5,1]){const p=plane();const box=[126,148,248,5];slice(p,load('experiencebarempty'),box,[6,1,6,1]);slice(p,load('experiencebarfull'),box,[1,0,1,0],248*fraction);save('bar-'+String(fraction).replace('.','_'),p,{barBox:box,nubBox:[131,148,238,5],sourceClipDirection:'left',sourceClipPixelperfect:false,finiteWebClipPolicy:'visible-fraction-web',fraction,visibleFullWidth:248*fraction,paintIsolation:'Only empty/full original material paint. Full-sized nub retains box but visibility:hidden; no frame/buttons/fonts/logo paint. Standalone bar placement is explicit test-host policy, not source stack/default-anchor recovery.'})}
const protocol={schema:1,status:'FROZEN BEFORE ROOT MEASUREMENT',scope:'Finite Web original-material frame+fill and empty/fullbar planes only; not native GUI, font, percentage parsing, default anchors, source percentage evaluator, tile origin, or layer sorting certification.',sourceArchive:{path:'.cache/references/bedrock-samples-v1.26.60.5-full.zip',bytes:169569258,sha256:'d93dea9aa1fb241a3184cc9f9a074a2ff34bd1b3c00d859b09c24b4b9e4e9adf'},sourceRoot:'ORIGINALS',host:{width:W,height:H,scale:1,deviceScaleFactor:1,backdrop:'#203040',alpha:255},sampling:{mapper:'Independent piecewise point pull at output pixel centers: leading/trailing slices1:1; center floor((i-leading+.5)*sourceCenter/destCenter).',layering:'control fill first then frame. Bar empty first then full image clip; nub paint hidden only.',alpha:'straight RGBA byte source-over onto opaque output; round nearest byte each layer. Frame/bar binary alpha; uniform controlRGB9 alpha.8 gives rounded(14,17,20) over#203040; no .5ties.',tolerance:0,mask:null,compare:'all500×301×4 bytes; whole planes, external backdrop included'},notQualified:['native clip_ratio direction/range/out-of-range and rounding','native omitted anchors and sizes','conditional stack layout/collapse and source %c evaluator','native tiled nub phase/stretch/alpha and GPU premultiplication','native font/rendering, title assets/position, source input lifecycle','full-screen safezone, background loading bars and animations'],cases};
const bytes=Buffer.from(JSON.stringify(protocol,null,2)+'\n');fs.writeFileSync(path.join(root,'MATERIAL-PROTOCOL.FROZEN.json'),bytes);fs.writeFileSync(path.join(root,'MATERIAL-PROTOCOL.FROZEN.sha256'),hash(bytes)+'  MATERIAL-PROTOCOL.FROZEN.json\n');console.log(JSON.stringify({protocolSha256:hash(bytes),cases:cases.map(c=>({id:c.id,rgbaSha256:c.rgbaSha256,pngSha256:c.pngSha256}))},null,2));
